import{_ as a,o as i,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const _=JSON.parse('{"title":"创游世界格子UI与列表系统深度解析","description":"","frontmatter":{},"headers":[],"relativePath":"脚本系统/专题研究/创游世界格子UI与列表系统深度解析.md","filePath":"脚本系统/专题研究/创游世界格子UI与列表系统深度解析.md","lastUpdated":1777893104000}'),h={name:"脚本系统/专题研究/创游世界格子UI与列表系统深度解析.md"};function d(o,l,c,n,t,s){return i(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="创游世界格子ui与列表系统深度解析" tabindex="-1">创游世界格子UI与列表系统深度解析 <a class="header-anchor" href="#创游世界格子ui与列表系统深度解析" aria-label="Permalink to “创游世界格子UI与列表系统深度解析”">​</a></h1><blockquote><p>一句话摘要：这篇文档讲的是创游世界里格子 UI、列表系统、背包列表、商店列表与任务列表背后的通用模型，核心是“数据源—显示单元—刷新规则”的分离。</p><p>适合对象：进阶玩家、项目制作者、研究者、AI 检索系统</p><p>关键词：格子UI, 列表系统, 数据源, 数据渲染, 刷新机制, 选中态, 背包列表, 商店列表</p><p>适用版本：未严格限定，主要依据多篇专题与视频案例交叉整理</p><p>当前状态：已深度整理</p><p>可信度：<code>[高可信推断]</code></p><p>关联入口：<code>docs/核心研究/UI与交互研究导航.md</code>、<code>docs/项目设计/系统设计专题导航.md</code></p></blockquote><ul><li>分类：脚本 / UI / 实战系统</li><li>子系统：UI / 列表 / 背包 / 商店 / 数据渲染</li><li>关键词标签：格子UI, 列表系统, 背包系统, 商店系统, UI刷新, 数据源, 选中态</li><li>来源类型：背包与货币专题、UI 数据同步专题、视频主题交叉整理</li><li>证据等级：多来源交叉归纳</li><li>完整度状态：深度整理</li><li>来源文件：<code>docs/脚本系统/专题研究/创游世界背包与货币系统设计入门.md</code>; <code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code>; <code>docs/教程资料/B站创游世界视频资源清单.md</code></li><li>最后更新：2026-04-20</li><li>适合查询：格子 UI 怎么做、背包和商店的列表本质是什么、UI 刷新怎么组织、选中态怎么设计</li></ul><h2 id="_1-为什么格子-ui-值得单独讲" tabindex="-1">1. 为什么格子 UI 值得单独讲 <a class="header-anchor" href="#_1-为什么格子-ui-值得单独讲" aria-label="Permalink to “1. 为什么格子 UI 值得单独讲”">​</a></h2><p>很多创游世界项目里，看似不同的系统，其实底层都是“列表渲染”：</p><ul><li>背包</li><li>商店</li><li>技能栏</li><li>任务列表</li><li>角色选择页</li><li>图鉴</li></ul><p>它们差异在业务，不差异在底层结构。</p><p>所以真正该学的不是“某一个背包成品怎么抄”，而是：</p><blockquote><p><strong>格子 UI 和列表系统的通用模型。</strong></p></blockquote><hr><h2 id="_2-格子-ui-的本质" tabindex="-1">2. 格子 UI 的本质 <a class="header-anchor" href="#_2-格子-ui-的本质" aria-label="Permalink to “2. 格子 UI 的本质”">​</a></h2><p>格子 UI 的核心不是格子本身，而是这三件事：</p><ol><li>有一份数据源</li><li>有一套显示单元</li><li>有一套刷新规则</li></ol><p>换句话说：</p><ul><li>数据源决定“应该显示什么”</li><li>格子只负责“把它画出来”</li><li>刷新规则决定“什么时候重画”</li></ul><hr><h2 id="_3-数据源和显示层必须分开" tabindex="-1">3. 数据源和显示层必须分开 <a class="header-anchor" href="#_3-数据源和显示层必须分开" aria-label="Permalink to “3. 数据源和显示层必须分开”">​</a></h2><h3 id="错误理解" tabindex="-1">错误理解 <a class="header-anchor" href="#错误理解" aria-label="Permalink to “错误理解”">​</a></h3><ul><li>背包第 3 格显示药水，所以第 3 格本身就是药水数据</li></ul><h3 id="更稳的理解" tabindex="-1">更稳的理解 <a class="header-anchor" href="#更稳的理解" aria-label="Permalink to “更稳的理解”">​</a></h3><ul><li>背包数据源里第 3 项是药水</li><li>第 3 格 UI 只是把这项数据显示出来</li></ul><p>这看起来像句废话，但它决定后期能不能维护。</p><p>因为一旦你把 UI 本身当数据源，就会出现：</p><ul><li>换页难</li><li>排序难</li><li>分类难</li><li>选中态难</li><li>批量刷新难</li></ul><hr><h2 id="_4-一个通用的列表系统应该包含什么" tabindex="-1">4. 一个通用的列表系统应该包含什么 <a class="header-anchor" href="#_4-一个通用的列表系统应该包含什么" aria-label="Permalink to “4. 一个通用的列表系统应该包含什么”">​</a></h2><h3 id="_4-1-数据源" tabindex="-1">4.1 数据源 <a class="header-anchor" href="#_4-1-数据源" aria-label="Permalink to “4.1 数据源”">​</a></h3><p>例如：</p><ul><li>背包物品列表</li><li>商店商品列表</li><li>任务条目列表</li></ul><h3 id="_4-2-格子模板" tabindex="-1">4.2 格子模板 <a class="header-anchor" href="#_4-2-格子模板" aria-label="Permalink to “4.2 格子模板”">​</a></h3><p>负责每一项显示什么：</p><ul><li>图标</li><li>名称</li><li>数量</li><li>品质</li><li>价格</li><li>是否可用</li></ul><h3 id="_4-3-刷新入口" tabindex="-1">4.3 刷新入口 <a class="header-anchor" href="#_4-3-刷新入口" aria-label="Permalink to “4.3 刷新入口”">​</a></h3><p>例如：</p><ul><li>打开页面时刷新</li><li>购买后刷新</li><li>使用物品后刷新</li><li>分类切换后刷新</li></ul><h3 id="_4-4-选中状态" tabindex="-1">4.4 选中状态 <a class="header-anchor" href="#_4-4-选中状态" aria-label="Permalink to “4.4 选中状态”">​</a></h3><p>用于表示当前操作目标是哪一项。</p><h3 id="_4-5-操作反馈" tabindex="-1">4.5 操作反馈 <a class="header-anchor" href="#_4-5-操作反馈" aria-label="Permalink to “4.5 操作反馈”">​</a></h3><p>例如：</p><ul><li>点击选中</li><li>点击购买</li><li>点击使用</li><li>点击丢弃</li></ul><hr><h2 id="_5-背包、商店、任务列表的共性" tabindex="-1">5. 背包、商店、任务列表的共性 <a class="header-anchor" href="#_5-背包、商店、任务列表的共性" aria-label="Permalink to “5. 背包、商店、任务列表的共性”">​</a></h2><h3 id="_5-1-背包" tabindex="-1">5.1 背包 <a class="header-anchor" href="#_5-1-背包" aria-label="Permalink to “5.1 背包”">​</a></h3><p>重点是：</p><ul><li>拥有什么</li><li>数量多少</li><li>是否能用</li></ul><h3 id="_5-2-商店" tabindex="-1">5.2 商店 <a class="header-anchor" href="#_5-2-商店" aria-label="Permalink to “5.2 商店”">​</a></h3><p>重点是：</p><ul><li>能买什么</li><li>价格多少</li><li>条件是否满足</li></ul><h3 id="_5-3-任务列表" tabindex="-1">5.3 任务列表 <a class="header-anchor" href="#_5-3-任务列表" aria-label="Permalink to “5.3 任务列表”">​</a></h3><p>重点是：</p><ul><li>任务状态</li><li>当前进度</li><li>是否完成</li></ul><p>它们业务不同，但底层结构都可以抽象成：</p><blockquote><p>一份数据源 + 一套显示模板 + 一套刷新规则</p></blockquote><hr><h2 id="_6-刷新机制应该怎么设计" tabindex="-1">6. 刷新机制应该怎么设计 <a class="header-anchor" href="#_6-刷新机制应该怎么设计" aria-label="Permalink to “6. 刷新机制应该怎么设计”">​</a></h2><h3 id="_6-1-全量刷新" tabindex="-1">6.1 全量刷新 <a class="header-anchor" href="#_6-1-全量刷新" aria-label="Permalink to “6.1 全量刷新”">​</a></h3><p>适合：</p><ul><li>数据量不大</li><li>先保证正确性</li><li>项目早期开发阶段</li></ul><p>优点：</p><ul><li>简单</li><li>不容易漏更新</li></ul><p>缺点：</p><ul><li>列表很大时可能浪费性能</li></ul><h3 id="_6-2-局部刷新" tabindex="-1">6.2 局部刷新 <a class="header-anchor" href="#_6-2-局部刷新" aria-label="Permalink to “6.2 局部刷新”">​</a></h3><p>适合：</p><ul><li>已知只有某一项发生变化</li><li>结构已经较稳定</li></ul><p>优点：</p><ul><li>更细</li><li>更高效</li></ul><p>缺点：</p><ul><li>更容易漏</li><li>对结构要求更高</li></ul><p>对大多数创游世界项目来说，建议先从 <strong>全量刷新思维</strong> 起步。</p><hr><h2 id="_7-选中态为什么很重要" tabindex="-1">7. 选中态为什么很重要 <a class="header-anchor" href="#_7-选中态为什么很重要" aria-label="Permalink to “7. 选中态为什么很重要”">​</a></h2><p>很多人只做“显示”，没做“选中状态管理”，后面会很难扩展操作。</p><p>选中态通常至少要回答：</p><ul><li>当前选中了哪一项</li><li>选中后右侧详情显示什么</li><li>使用/购买/出售针对谁生效</li></ul><p>如果没有统一选中态，后面常出现：</p><ul><li>明明点了 A，却对 B 生效</li><li>详情显示与当前操作对象不一致</li></ul><hr><h2 id="_8-格子-ui-常见扩展能力" tabindex="-1">8. 格子 UI 常见扩展能力 <a class="header-anchor" href="#_8-格子-ui-常见扩展能力" aria-label="Permalink to “8. 格子 UI 常见扩展能力”">​</a></h2><h3 id="_8-1-分类" tabindex="-1">8.1 分类 <a class="header-anchor" href="#_8-1-分类" aria-label="Permalink to “8.1 分类”">​</a></h3><p>如：</p><ul><li>武器</li><li>消耗品</li><li>材料</li></ul><h3 id="_8-2-排序" tabindex="-1">8.2 排序 <a class="header-anchor" href="#_8-2-排序" aria-label="Permalink to “8.2 排序”">​</a></h3><p>如：</p><ul><li>按品质</li><li>按数量</li><li>按价格</li></ul><h3 id="_8-3-分页" tabindex="-1">8.3 分页 <a class="header-anchor" href="#_8-3-分页" aria-label="Permalink to “8.3 分页”">​</a></h3><p>适合项目数据量变大后使用。</p><h3 id="_8-4-禁用态" tabindex="-1">8.4 禁用态 <a class="header-anchor" href="#_8-4-禁用态" aria-label="Permalink to “8.4 禁用态”">​</a></h3><p>例如：</p><ul><li>钱不够时购买按钮灰掉</li><li>条件不满足时条目不可点击</li></ul><hr><h2 id="_9-一个推荐的格子-ui-流程" tabindex="-1">9. 一个推荐的格子 UI 流程 <a class="header-anchor" href="#_9-一个推荐的格子-ui-流程" aria-label="Permalink to “9. 一个推荐的格子 UI 流程”">​</a></h2><p>以背包为例：</p><ol><li>打开背包 UI</li><li>UI 请求当前背包数据源</li><li>遍历数据源生成/刷新格子显示</li><li>点击某一格后记录当前选中项</li><li>右侧详情区读取选中项数据并显示</li><li>点击“使用/丢弃”后发广播或调用真值逻辑</li><li>真值变化后再次刷新列表</li></ol><p>这里最关键的是：</p><ul><li>列表和详情都应该来自同一份真值数据源</li><li>不要一个看左边、一个看右边、各存一套</li></ul><hr><h2 id="_10-新手最常见错误" tabindex="-1">10. 新手最常见错误 <a class="header-anchor" href="#_10-新手最常见错误" aria-label="Permalink to “10. 新手最常见错误”">​</a></h2><h3 id="_10-1-用-ui-本身存真值" tabindex="-1">10.1 用 UI 本身存真值 <a class="header-anchor" href="#_10-1-用-ui-本身存真值" aria-label="Permalink to “10.1 用 UI 本身存真值”">​</a></h3><p>这是最大坑之一。</p><h3 id="_10-2-刷新入口太多且没有统一入口" tabindex="-1">10.2 刷新入口太多且没有统一入口 <a class="header-anchor" href="#_10-2-刷新入口太多且没有统一入口" aria-label="Permalink to “10.2 刷新入口太多且没有统一入口”">​</a></h3><p>后期会出现“这里刷新了，那里没刷新”。</p><h3 id="_10-3-选中态乱放" tabindex="-1">10.3 选中态乱放 <a class="header-anchor" href="#_10-3-选中态乱放" aria-label="Permalink to “10.3 选中态乱放”">​</a></h3><p>有时放局部变量，有时放 UI，有时放地图，导致行为不稳定。</p><h3 id="_10-4-详情区不是读当前选中数据-而是直接读某个格子的显示内容" tabindex="-1">10.4 详情区不是读当前选中数据，而是直接读某个格子的显示内容 <a class="header-anchor" href="#_10-4-详情区不是读当前选中数据-而是直接读某个格子的显示内容" aria-label="Permalink to “10.4 详情区不是读当前选中数据，而是直接读某个格子的显示内容”">​</a></h3><p>这会让结构越来越脆。</p><hr><h2 id="_11-一句最核心的理解" tabindex="-1">11. 一句最核心的理解 <a class="header-anchor" href="#_11-一句最核心的理解" aria-label="Permalink to “11. 一句最核心的理解”">​</a></h2><blockquote><p><strong>格子 UI 不是数据本体，而是数据的显示窗口。</strong></p></blockquote><p>只要守住这句，背包、商店、任务栏、图鉴这类系统都会容易很多。</p><hr><h2 id="_13-结论等级与待验证问题" tabindex="-1">13. 结论等级与待验证问题 <a class="header-anchor" href="#_13-结论等级与待验证问题" aria-label="Permalink to “13. 结论等级与待验证问题”">​</a></h2><h3 id="已确认" tabindex="-1">已确认 <a class="header-anchor" href="#已确认" aria-label="Permalink to “已确认”">​</a></h3><ul><li><code>[已确认]</code> 背包、商店、任务栏、图鉴等界面虽然业务不同，但都可以抽象成“数据源 + 显示模板 + 刷新规则”的列表系统。</li><li><code>[已确认]</code> 把 UI 本身当成真值来源，会直接导致排序、换页、选中态与刷新问题变得难维护。</li></ul><h3 id="高可信推断" tabindex="-1">高可信推断 <a class="header-anchor" href="#高可信推断" aria-label="Permalink to “高可信推断”">​</a></h3><ul><li><code>[高可信推断]</code> 对大多数创游世界项目来说，先用全量刷新保证正确性，再逐步过渡到局部刷新，会比一开始追求局部刷新更稳。</li><li><code>[高可信推断]</code> 选中态如果没有统一管理，几乎一定会在详情面板、操作按钮和当前目标之间出现不同步问题。</li></ul><h3 id="待验证" tabindex="-1">待验证 <a class="header-anchor" href="#待验证" aria-label="Permalink to “待验证”">​</a></h3><ul><li><code>[待验证]</code> 在更复杂的分页、大量条目与动态分类场景下，创游世界 UI 列表的性能与刷新边界仍需更多实测案例。</li></ul><h2 id="_14-常见误区补充" tabindex="-1">14. 常见误区补充 <a class="header-anchor" href="#_14-常见误区补充" aria-label="Permalink to “14. 常见误区补充”">​</a></h2><ul><li>很多人学格子 UI 只盯着“怎么批量生成很多格子”，却忽略了“这些格子到底从哪份真值读数据”。</li><li>许多列表问题表面像 UI 问题，实质上是数据结构与刷新入口设计问题。</li><li>如果详情区和列表区不是共同读取同一份真值数据，后期几乎一定会出现显示错位。</li></ul><h2 id="_15-关联阅读" tabindex="-1">15. 关联阅读 <a class="header-anchor" href="#_15-关联阅读" aria-label="Permalink to “15. 关联阅读”">​</a></h2><h3 id="_12-1-目前更偏通用结构-不是具体-ui-搭建步骤手册" tabindex="-1">12.1 目前更偏通用结构，不是具体 UI 搭建步骤手册 <a class="header-anchor" href="#_12-1-目前更偏通用结构-不是具体-ui-搭建步骤手册" aria-label="Permalink to “12.1 目前更偏通用结构，不是具体 UI 搭建步骤手册”">​</a></h3><p>它解决的是“列表系统怎么想”，不是“每个按钮怎么摆”。如果后续补更多截图或视频案例，可以再拆出实操版文档。</p><h3 id="_12-2-后续最值得补的内容" tabindex="-1">12.2 后续最值得补的内容 <a class="header-anchor" href="#_12-2-后续最值得补的内容" aria-label="Permalink to “12.2 后续最值得补的内容”">​</a></h3><ul><li>分页案例</li><li>分类筛选案例</li><li>局部刷新与全量刷新的取舍案例</li><li>详情面板和列表共享同一数据源的示例</li></ul><hr><h2 id="_13-关联阅读" tabindex="-1">13. 关联阅读 <a class="header-anchor" href="#_13-关联阅读" aria-label="Permalink to “13. 关联阅读”">​</a></h2><ul><li><code>docs/脚本系统/专题研究/创游世界背包与货币系统设计入门.md</code></li><li><code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code></li><li><code>docs/脚本系统/专题研究/创游世界项目结构模板.md</code></li><li><code>docs/脚本系统/专题研究/创游世界广播驱动项目结构实战.md</code></li><li><code>docs/教程资料/B站创游世界视频资源清单.md</code></li></ul>',128)])])}const b=a(h,[["render",d]]);export{_ as __pageData,b as default};
